export interface BeadImage {
  /** matches a Step's slug exactly, e.g. 'annunciation-hail-mary-9' */
  slug: string;
  file: string; // e.g. '/images/beads/annunciation-hail-mary-9.jpg'
  title: string;
  artist: string;
  source: string;
}

export function getBeadImage(slug: string): BeadImage | undefined {
  return beadImages.find((img) => img.slug === slug);
}

